import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.CANn83f8.js";const h=JSON.parse('{"title":"Complete account setup","description":"Import transaction history and finish the ExpenseAutomator setup checklist.","frontmatter":{"title":"Complete account setup","description":"Import transaction history and finish the ExpenseAutomator setup checklist.","aside":false,"prev":{"text":"Create your account","link":"/getting-started/create-account"},"next":{"text":"Importing transactions","link":"/guide/importing-transactions"}},"headers":[],"relativePath":"getting-started/account-setup.md","filePath":"getting-started/account-setup.md","lastUpdated":1790625501000}'),o={name:"getting-started/account-setup.md"};function r(n,e,c,p,l,d){return a(),i("div",null,[...e[0]||(e[0]=[s('<div class="doc-eyebrow">Getting started</div><h1 id="complete-account-setup" tabindex="-1">Complete account setup <a class="header-anchor" href="#complete-account-setup" aria-label="Permalink to &quot;Complete account setup&quot;">​</a></h1><p>The setup checklist turns transaction history into a useful starting point for your account.</p><p>Your progress is saved, so you can return to unfinished steps after signing in. The available steps depend on your plan and the financial activity imported into your account.</p><h2 id="follow-the-checklist" tabindex="-1">Follow the checklist <a class="header-anchor" href="#follow-the-checklist" aria-label="Permalink to &quot;Follow the checklist&quot;">​</a></h2><div class="steps"><div class="step"><h3>Confirm plan and billing</h3><p>Review the plan associated with your account and complete any required subscription step.</p></div><div class="step"><h3>Import transaction files</h3><p>Add up to ten original CSV files at a time. Each file can be up to 5 MB. Supported bank formats are detected automatically.</p></div><div class="step"><h3>Review the financial analysis</h3><p>Use the imported activity to review the initial picture of income, spending, and financial health.</p></div><div class="step"><h3>Shape proposed budgets</h3><p>Review the starting budgets suggested from your activity and adjust them to match your priorities.</p></div><div class="step"><h3>Confirm recurring activity</h3><p>Check transactions identified as recurring so future views can represent regular commitments more accurately.</p></div><div class="step"><h3>Create a first goal</h3><p>Add a target you want to track, then review the setup summary and finish onboarding.</p></div></div><h2 id="while-files-are-processing" tabindex="-1">While files are processing <a class="header-anchor" href="#while-files-are-processing" aria-label="Permalink to &quot;While files are processing&quot;">​</a></h2><p>Uploaded files move through format detection, transaction import, and categorisation. Keep the setup page open while processing continues. If one file fails, the page shows its error and provides a retry action.</p><p>Duplicate transactions are skipped. A completed file reports its detected bank, the number imported, and the number of duplicates found.</p><h2 id="after-setup" tabindex="-1">After setup <a class="header-anchor" href="#after-setup" aria-label="Permalink to &quot;After setup&quot;">​</a></h2><p>You will arrive at the main application with access to your dashboard and the features included in your plan. Start by checking the imported totals and uncategorised transactions before relying on reports or budget comparisons.</p>',11)])])}const f=t(o,[["render",r]]);export{h as __pageData,f as default};
